import{_ as e,c as r,o as i,ap as t}from"./chunks/framework.BVMg0REN.js";const g=JSON.parse('{"title":"开发工具介绍","description":"","frontmatter":{},"headers":[],"relativePath":"Developer/0.1-开发工具介绍.md","filePath":"zh/Developer/0.1-开发工具介绍.md","lastUpdated":1780998854000}'),l={name:"Developer/0.1-开发工具介绍.md"};function s(o,a,h,n,p,d){return i(),r("div",null,a[0]||(a[0]=[t('<h1 id="开发工具介绍" tabindex="-1"><i class="ri-tools-line"></i>开发工具介绍 <a class="header-anchor" href="#开发工具介绍" aria-label="Permalink to “开发工具介绍”">​</a></h1><p>Maa调试/开发工具总览：<a href="https://github.com/MaaXYZ/MaaFramework#%E7%A4%BE%E5%8C%BA%E9%A1%B9%E7%9B%AE" target="_blank" rel="noreferrer">MaaFramework#社区项目</a></p><table tabindex="0"><thead><tr><th>工具</th><th>简介</th></tr></thead><tbody><tr><td><a href="https://github.com/MaaXYZ/MaaDebugger" target="_blank" rel="noreferrer">MaaDebugger</a></td><td>独立调试工具</td></tr><tr><td><a href="https://marketplace.visualstudio.com/items?itemName=nekosu.maa-support" target="_blank" rel="noreferrer">Maa Pipeline Support</a></td><td>VSCode 插件，提供调试、截图、获取 ROI 、取色等功能</td></tr><tr><td><a href="https://github.com/SweetSmellFox/MFAToolsPlus" target="_blank" rel="noreferrer">MFA Tools Plus</a></td><td>独立截图、获取 ROI 、滑动、文字及取色工具</td></tr><tr><td><a href="https://github.com/Windsland52/MAALogAnalyzer" target="_blank" rel="noreferrer">MaaLogAnalyzer</a></td><td>可视化分析基于 MaaFramework 开发应用的日志</td></tr><tr><td><a href="https://mpe.codax.site/stable/" target="_blank" rel="noreferrer">MaaPipelineExtremer - Editor</a></td><td>MPE网站，可视化编辑和分析MaaLYSK的流程代码</td></tr></tbody></table><h2 id="maa-pipeline-support" tabindex="-1">Maa Pipeline Support <a class="header-anchor" href="#maa-pipeline-support" aria-label="Permalink to “Maa Pipeline Support”">​</a></h2><p>官方使用教程：<a href="https://docs.maa.plus/zh-cn/develop/vsc-ext-tutorial.html" target="_blank" rel="noreferrer">专用 VSCode 插件教程 | MAA 文档站</a></p><h3 id="_1-安装" tabindex="-1">1. 安装 <a class="header-anchor" href="#_1-安装" aria-label="Permalink to “1. 安装”">​</a></h3><p>在VScode插件模块中搜索 <code>Maa Pipeline Support</code></p><h3 id="_2-连接" tabindex="-1">2. 连接 <a class="header-anchor" href="#_2-连接" aria-label="Permalink to “2. 连接”">​</a></h3><p>打开插件页面，连接模拟器，以进行截图、调试等操作</p><p>编辑好pipeline对应的interface后，想看选项、完整的一个任务能不能正常实现，也在此页面进行任务选择与启动。</p><h3 id="_3-截图、roi" tabindex="-1">3. 截图、ROI <a class="header-anchor" href="#_3-截图、roi" aria-label="Permalink to “3. 截图、ROI”">​</a></h3><p>打开插件截图小工具：</p><p><code>Ctrl+Shift+P</code>打开指令页面，输入maa（或者在maa插件页面点击按钮启动）</p><h3 id="_4-调试" tabindex="-1">4. 调试 <a class="header-anchor" href="#_4-调试" aria-label="Permalink to “4. 调试”">​</a></h3><ul><li>执行某一个节点（<code>Pipeline</code>里）</li></ul><p>也可以 <code>Ctrl+Shift+P</code>打开指令页面，输入maa，在 <code>maa:launch task</code>中选择对应的节点执行</p><ul><li>执行整个任务（<code>interface</code>配置好任务以及对应选项后）</li></ul><p>在VSCode插件工具页面，最下方<code>任务</code>-<strong>选择对应任务，点击</strong> <code>启动</code>**执行任务。</p><h2 id="maadebugger" tabindex="-1">MaaDebugger <a class="header-anchor" href="#maadebugger" aria-label="Permalink to “MaaDebugger”">​</a></h2><p>MaaDebugger是MaaFW官方提供的调试工具，采用命令行下载。</p><p>官方网站：<a href="https://github.com/MaaXYZ/MaaDebugger" target="_blank" rel="noreferrer">MaaXYZ/Maa调试器</a></p><p>环境需求：</p><ul><li>Python &gt;= 3.9，&lt;= 3.13</li><li>nicegui &gt;= 2.21，&lt; 3.0</li></ul><h3 id="_1-下载" tabindex="-1">1. 下载 <a class="header-anchor" href="#_1-下载" aria-label="Permalink to “1. 下载”">​</a></h3><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MaaDebugger</span></span></code></pre></div><h3 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to “2. 使用”">​</a></h3><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MaaDebugger</span></span></code></pre></div><p>输入指令后，会打开一个网页，在此页面配置，连接模拟器和本地开发文件夹，确保模拟器的后台保活关闭后，即可开始调试。</p><ul><li><strong>ADB Path</strong></li></ul><p>搜索模拟器+连接。</p><p>先点<code>find</code>，右侧会显示你的模拟器。</p><p>然后再点<code>connect</code>，🟢亮绿灯表示连接成功，会有个小窗显示模拟器画面。</p><ul><li><strong>Resource Directory</strong></li></ul><p>填克隆后MAAYuan库对应的位置<strong>（</strong>要写到图上这个层级，简中最后是<code>base</code>，繁中最后是**<code>zh_tw</code>）。</p><p>写好的.json文件应该放到<code>\\resource\\简中base或者繁中zh_tw选一个填\\pipeline</code>里，点<code>load</code>。</p><p>🟢亮绿灯就是准备好了，如果🔴亮红灯说明json文件里有地方写错了。</p><ul><li><strong>Task Entry</strong></li></ul><p>填<code>.json</code>文件里面任意一个&quot;子任务名&quot;，再点<code>start</code>，就可以看到实际运行效果。</p><ul><li><strong>Pipeline Override</strong></li></ul><p>根据需求不同（比如选项内容）来改变（=替换）原任务.json中某些步骤的效果。</p><p>💡 <strong>如果调试中改了 <code>.json</code> 文件，点一下 resource 的 <code>load</code> 就能更新了。</strong>（要确保你的文件是<strong>保存</strong>过的）</p><h3 id="_3-更新" tabindex="-1">3. 更新 <a class="header-anchor" href="#_3-更新" aria-label="Permalink to “3. 更新”">​</a></h3><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MaaDebugger</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MaaFW</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --upgrade</span></span></code></pre></div><h2 id="maapipelineextremer-editor-可视化-maafw-pipeline-编辑器" tabindex="-1">MaaPipelineExtremer - Editor：可视化 MaaFW Pipeline 编辑器 <a class="header-anchor" href="#maapipelineextremer-editor-可视化-maafw-pipeline-编辑器" aria-label="Permalink to “MaaPipelineExtremer - Editor：可视化 MaaFW Pipeline 编辑器”">​</a></h2><h3 id="_1-使用-在线网址" tabindex="-1">1. 使用：在线网址 <a class="header-anchor" href="#_1-使用-在线网址" aria-label="Permalink to “1. 使用：在线网址”">​</a></h3><p>网址：<a href="https://mpe.codax.site/stable/" target="_blank" rel="noreferrer">MaaPipelineExtremer - Editor</a></p><p>官方使用教程：<a href="https://mpe.codax.site/docs/" target="_blank" rel="noreferrer">MaaPipelineEditor文档站</a></p><blockquote><p>可以利用可视化网站，查看别人的/自己的代码，梳理自己的思路</p></blockquote><h3 id="_2-更多功能" tabindex="-1">2. 更多功能 <a class="header-anchor" href="#_2-更多功能" aria-label="Permalink to “2. 更多功能”">​</a></h3><p>利用MPE的本地服务功能，也可以实现调试功能，具体参照MPE官方使用教程。</p><h2 id="mfatoolsplus" tabindex="-1">MFAToolsPlus <a class="header-anchor" href="#mfatoolsplus" aria-label="Permalink to “MFAToolsPlus”">​</a></h2><p>项目地址：<a href="https://github.com/SweetSmellFox/MFAToolsPlus" target="_blank" rel="noreferrer">MFAToolsPlus： 基于 Avalonia 的 MAAFramework 辅助工具</a></p><h3 id="_1-下载-1" tabindex="-1">1. 下载 <a class="header-anchor" href="#_1-下载-1" aria-label="Permalink to “1. 下载”">​</a></h3><p>从项目地址下载后，解压运行可执行文件，即可使用小工具（和MaaLYSK一样，记得连模拟器）</p><h3 id="_2-使用-1" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用-1" aria-label="Permalink to “2. 使用”">​</a></h3><p>利用此工具，可以很方便地进行取色、截图、取roi、取roi_offset、滑动起终点等操作。</p><p>特色功能：</p><ul><li>实时预览</li><li>取色可以单显显示范围</li><li>可以设置 <code>“字段名+值”</code>的方式，方便粘贴到VSCode</li></ul><h2 id="maaloganalyzer" tabindex="-1">MaaLogAnalyzer <a class="header-anchor" href="#maaloganalyzer" aria-label="Permalink to “MaaLogAnalyzer”">​</a></h2><p>在线网址：<a href="https://maaloganalyzer.maafw.com/" target="_blank" rel="noreferrer">MAA 日志分析器</a></p><p>项目地址：<a href="https://github.com/Windsland52/MAALogAnalyzer" target="_blank" rel="noreferrer">MaaLogAnalyzer项目库</a></p><h3 id="_1-使用" tabindex="-1">1. 使用 <a class="header-anchor" href="#_1-使用" aria-label="Permalink to “1. 使用”">​</a></h3><p>打开在线网址，上传maa.log即可进行日志分析、文本搜索等操作。</p><h3 id="_2-bug排查" tabindex="-1">2. BUG排查 <a class="header-anchor" href="#_2-bug排查" aria-label="Permalink to “2. BUG排查”">​</a></h3><p>直接看M9A的相关说明吧！<a href="https://1999.fan/zh_cn/develop/fix.html" target="_blank" rel="noreferrer">Bug 排查 | M9A 文档站</a></p>',65)]))}const k=e(l,[["render",s]]);export{g as __pageData,k as default};
